(() => {
  const plan = context.item.data?.['plan']; 
  if (!plan) return "";

  if (plan === 'essai') {
    return "Essai gratuit";
  }

  return "Plan " + plan.charAt(0).toUpperCase() + plan.slice(1);
})()

(() => {

  // CAS TRIAL ACTIF
  if (context.item.data?.['plan']=== 'essai' 
      &&context.item.data?.['status']=== 'active') {
    return "Encore " +context.item.data?.['trial_credits']+ " QCM Court disponible";
  }

  // CAS TRIAL EXPIRE
  if (context.item.data?.['plan']=== 'essai' 
      &&context.item.data?.['status']=== 'expired') {
    return "Améliorez votre plan pour débloquer l’accès complet";
  }

  // FORMAT DATE
  const formattedDate = context.item.data?.['expires_at']     ? new Date(context.item.data?.['expires_at']).toLocaleDateString('fr-FR', {
        day: '2-digit',
        month: 'long',
        year: 'numeric'
      })
    : '';

  // TEXTE DATE
  const dateText = context.item.data?.['status']=== 'active'
    ? "Actif jusqu’au "
    : "A expiré le ";

  return dateText + formattedDate;

})();

(() => {

  const ecoleIdsRaw = context.item.data?.['ecoles']; 
  if (!ecoleIdsRaw) return "";

  const ecoleIds = Array.isArray(ecoleIdsRaw)
    ? ecoleIdsRaw.map(id => Number(id))
    : [Number(ecoleIdsRaw)];

  const allEcoles = collections['19277214-0110-41c3-836c-b88bc75da7fe']?.data ?? [];

  const labels = allEcoles
    .filter(e => ecoleIds.includes(Number(e.id)))
    .map(e => e.nom);

  if (!labels.length) return "";

  return "(" + labels.join(" - ") + ")";

})();
